energy.code:
/-- Integer-valued energy, with the sign convention in the paper. -/
def energy (S : Sequence) (f : Fold G S.length) : ℤ :=
  -(bondCount S f : ℤ)

perfectEncoding.code:
/-- Section 2's perfect-fold input: tagged residues, separator, binary n.
Length = |S| + 1 + bitlength(n). Binary is economical even for malformed inputs;
on valid inputs with n>0, the explicit sequence already has at least n³ symbols. -/
def perfectEncoding : FinEncoding PerfectInput :=
  pairEncoding sequenceEncoding finEncodingNatBool

NPComplete.code:
/-- Membership in NP together with universal Karp NP-hardness. -/
def NPComplete {A : Type} (ea : FinEncoding A) (L : A → Prop) : Prop :=
  InNP ea L ∧ NPHard ea L

HPStringFold.code:
/-- HP STRING-FOLD on a specified graph, with the paper's integer threshold. -/
def HPStringFold (S : Sequence) (m : ℤ) : Prop :=
  ∃ f : Fold G S.length, m ≤ (bondCount S f : ℤ)

latticeDistance.code:
/-- Manhattan distance on the cubic lattice. -/
def latticeDistance (x y : Site) : ℕ :=
  ∑ k : Fin 3, (x k - y k).natAbs

cube.code:
/-- The n × n × n lattice cube with lower corner a. For n = 0 it is empty. -/
def cube (a : Site) (n : ℕ) : Set Site :=
  {p | ∀ k : Fin 3, a k ≤ p k ∧ p k < a k + (n : ℤ)}

hydrophobicSites.code:
/-- The sites occupied by H residues in a fold. -/
def hydrophobicSites (S : Sequence) (f : Fold cubicLattice S.length) : Set Site :=
  {p | ∃ i : Fin S.length, S.get i = Residue.H ∧ f.pos i = p}

cubeBondThreshold.code:
/-- The number of internal lattice edges in an n × n × n cube.
Natural subtraction also gives zero for the empty cube. -/
def cubeBondThreshold (n : ℕ) : ℤ := (3 * n ^ 2 * (n - 1) : ℕ)
